package org.sleepwell.app;

import android.content.*;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.time.*;
import java.util.*;

/** Private bounded diary confirmations. This preference file is deliberately not portable-record backup data. */
final class SRIReviews {
    interface Factory {SharedPreferences open(Context context);}
    static final Factory PRODUCTION=c->c.getSharedPreferences("sleepwell-sri-review",Context.MODE_PRIVATE);static Factory factory=PRODUCTION;
    private static final Object LOCK=new Object();private static final java.util.concurrent.atomic.AtomicLong changes=new java.util.concurrent.atomic.AtomicLong();
    static void changed(Context context){changes.incrementAndGet();}static long generation(){return changes.get();}static final int MAX_REVIEWS=90,MAX_BYTES=128*1024;
    static final class Review {
        final String date,zone,fingerprint;final long start,end,confirmed;
        Review(SRIModel.Day day,long confirmed){date=day.date.toString();zone=day.zone.getId();fingerprint=day.fingerprint;start=day.start;end=day.end;this.confirmed=confirmed;}
        Review(JSONObject value)throws JSONException{Set<String> keys=Set.of("date","zone","fingerprint","start","end","confirmed","all_sleep","no_travel");if(value.length()!=keys.size())throw new JSONException("Invalid day review");for(Iterator<String> names=value.keys();names.hasNext();)if(!keys.contains(names.next()))throw new JSONException("Unknown day review field");date=SensorProvenance.text(value,"date");zone=SensorProvenance.text(value,"zone");fingerprint=SensorProvenance.text(value,"fingerprint");start=SensorProvenance.whole(value,"start");end=SensorProvenance.whole(value,"end");confirmed=SensorProvenance.whole(value,"confirmed");try{LocalDate day=LocalDate.parse(date);ZoneId clock=ZoneId.of(zone);if(zone.length()>80||!fingerprint.matches("[a-f0-9]{64}")||end-start!=SRIModel.DAY||start!=day.atStartOfDay(clock).toInstant().toEpochMilli()||end!=day.plusDays(1).atStartOfDay(clock).toInstant().toEpochMilli()||confirmed<end||!(value.get("all_sleep") instanceof Boolean)||!value.getBoolean("all_sleep")||!(value.get("no_travel") instanceof Boolean)||!value.getBoolean("no_travel"))throw new JSONException("Invalid confirmation bounds");}catch(DateTimeException invalid){throw new JSONException("Invalid confirmation date or zone");}}
        String key(){return zone+"|"+date;}boolean matches(SRIModel.Day day){return date.equals(day.date.toString())&&zone.equals(day.zone.getId())&&start==day.start&&end==day.end&&fingerprint.equals(day.fingerprint);}
        JSONObject json()throws JSONException{return new JSONObject().put("date",date).put("zone",zone).put("fingerprint",fingerprint).put("start",start).put("end",end).put("confirmed",confirmed).put("all_sleep",true).put("no_travel",true);}
        boolean retained(long now){LocalDate today=Instant.ofEpochMilli(now).atZone(ZoneId.of(zone)).toLocalDate(),day=LocalDate.parse(date);return confirmed<=now&&day.isBefore(today)&&!day.isBefore(today.minusDays(90));}
    }
    static final class Saved {final List<Review> reviews;final long revision;final String epoch;final int expired;Saved(List<Review> values,long revision,String epoch,int expired){reviews=List.copyOf(values);this.revision=revision;this.epoch=epoch;this.expired=expired;}String stamp(){return epoch+":"+revision;}}
    static final class Snapshot {final SRIModel.Capture capture;final SRIModel.Day selected;final SRIModel.Summary summary;final Saved saved;Snapshot(SRIModel.Capture c,SRIModel.Day selected,SRIModel.Summary summary,Saved saved){capture=c;this.selected=selected;this.summary=summary;this.saved=saved;}Review confirmation(){for(Review value:saved.reviews)if(value.key().equals(selected.key()))return value;return null;}}
    static Snapshot read(Context context,Records.Factory records,Factory preferences,LocalDate day,ZoneId zone){requireScope(records,preferences);long now=System.currentTimeMillis();try(Store store=records.open(context)){SQLiteDatabase db=store.getReadableDatabase();db.beginTransactionNonExclusive();try{SRIModel.Capture capture=capture(store,now);Saved saved=load(preferences.open(context),now);Snapshot snapshot=new Snapshot(capture,capture.day(day,zone),new SRIModel.Summary(capture,zone,saved.reviews),saved);db.setTransactionSuccessful();return snapshot;}finally{db.endTransaction();}}}
    static void confirm(Context context,Records.Factory records,Factory preferences,SRIModel.Day expected,String expectedStamp,boolean allSleep,boolean noTravel){if(!allSleep||!noTravel)throw new IllegalArgumentException("Confirm all sleep is listed and that no time-zone travel occurred. Otherwise keep this day unknown.");requireScope(records,preferences);try(Store store=records.open(context)){SQLiteDatabase db=store.getReadableDatabase();db.beginTransactionNonExclusive();try{long now=System.currentTimeMillis();SRIModel.Day current=capture(store,now).day(expected.date,expected.zone);if(!current.reviewable(now))throw new IllegalArgumentException(current.issue.isEmpty()?"Only the past 30 completed days can be newly confirmed.":current.issue);if(!expected.fingerprint.equals(current.fingerprint)||expected.start!=current.start||expected.end!=current.end)throw new IllegalStateException("The sleep periods changed while you reviewed them. Reload this day and confirm the current list.");synchronized(LOCK){SharedPreferences prefs=preferences.open(context);Saved saved=load(prefs,now);if(!saved.stamp().equals(expectedStamp))throw new IllegalStateException("Day reviews changed or were erased. Reload before saving.");List<Review> next=new ArrayList<>(saved.reviews);next.removeIf(r->r.key().equals(current.key()));next.add(new Review(current,now));write(prefs,saved,next);}db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    static void remove(Context context,Factory preferences,String key,String expectedStamp){synchronized(LOCK){SharedPreferences prefs=preferences.open(context);Saved saved=load(prefs,System.currentTimeMillis());if(!saved.stamp().equals(expectedStamp))throw new IllegalStateException("Day reviews changed. Reload before removing a confirmation.");List<Review> next=new ArrayList<>(saved.reviews);next.removeIf(r->r.key().equals(key));write(prefs,saved,next);}}
    /** Call only after a successful production-history erase, on its existing worker. Revision/epoch reject old open forms. */
    static void erase(Context context){synchronized(LOCK){SharedPreferences prefs=PRODUCTION.open(context.getApplicationContext());long revision;try{revision=prefs.getLong("revision",0);}catch(RuntimeException corrupt){revision=0;}if(!prefs.edit().clear().putLong("revision",revision>=0&&revision<Long.MAX_VALUE?revision+1:0).putString("epoch",UUID.randomUUID().toString()).commit())throw new IllegalStateException("History was erased, but day-review preferences still need cleanup.");changes.incrementAndGet();}}
    static String viewZone(Context c){try{return ZoneId.of(factory.open(c).getString("view_zone",ZoneId.systemDefault().getId())).getId();}catch(RuntimeException ignored){return ZoneId.systemDefault().getId();}}
    static void viewZone(Context c,String value){ZoneId.of(value);factory.open(c).edit().putString("view_zone",value).apply();}
    private static SRIModel.Capture capture(Store store,long now){return new SRIModel.Capture(store.getDatabaseName(),Records.all(store),store.rows("SELECT id,start,source,zone,sensor FROM sessions WHERE end IS NULL ORDER BY id"),now);}
    private static Saved load(SharedPreferences preferences,long now){synchronized(LOCK){try{long revision=preferences.getLong("revision",0);String epoch=preferences.getString("epoch","");if(revision<0||!epoch.isEmpty()&&!UUID.fromString(epoch).toString().equals(epoch))throw new IllegalArgumentException();String raw=preferences.getString("reviews","[]");if(raw.length()>MAX_BYTES)throw new IllegalArgumentException();JSONArray rows=new JSONArray(raw);if(rows.length()>MAX_REVIEWS)throw new IllegalArgumentException();List<Review> kept=new ArrayList<>();Set<String> keys=new HashSet<>();int expired=0;for(int i=0;i<rows.length();i++){Review review=new Review(rows.getJSONObject(i));if(!keys.add(review.key()))throw new IllegalArgumentException();if(review.retained(now))kept.add(review);else expired++;}return new Saved(kept,revision,epoch,expired);}catch(Exception invalid){throw new IllegalStateException("Day-review preferences are unreadable. Existing sleep records were kept.",invalid);}}}
    private static void write(SharedPreferences preferences,Saved saved,List<Review> next){try{if(saved.revision==Long.MAX_VALUE)throw new IllegalStateException("Day-review revision is exhausted. Clear confirmations before continuing.");next.sort(Comparator.comparingLong((Review r)->r.start).thenComparingLong(r->r.confirmed).reversed());while(next.size()>MAX_REVIEWS)next.remove(next.size()-1);JSONArray rows=new JSONArray();for(Review review:next)rows.put(review.json());String encoded=rows.toString();if(encoded.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>MAX_BYTES)throw new IllegalStateException("Day-review preferences exceed their limit.");String epoch=saved.epoch.isEmpty()?UUID.randomUUID().toString():saved.epoch;if(!preferences.edit().putString("reviews",encoded).putLong("revision",saved.revision+1).putString("epoch",epoch).commit())throw new IllegalStateException("The day confirmation could not be saved.");changes.incrementAndGet();}catch(JSONException invalid){throw new IllegalStateException("The day confirmation could not be encoded.",invalid);}}
    private static void requireScope(Records.Factory records,Factory preferences){if(records!=Records.PRODUCTION&&preferences==PRODUCTION)throw new IllegalStateException("Day-review storage must match the private record source.");}
    private SRIReviews(){}
}
